import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Listen,
	Prop,
	h,
} from "@stencil/core";
// import { hasSlot } from "../../utils/slot";
import type { TreeNode } from "../../utils/tree";

import { caretLeft, caretRight } from "../../../icons/index";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

/**
 * @data-testid transfer--left-button - The control that moves selected items to the left list.
 * @data-testid transfer--right-button - The control that moves selected items to the right list.
 */
@Component({
	tag: "hbr-transfer",
	styleUrl: "transfer.scss",
	shadow: true,
	formAssociated: true,
})
export class Transfer {
	@Element() host: HTMLHbrTransferElement;

	/**
	 * Data for the transfer component in the form of an array of two treenode objects. The first object is the data in the first(left) list and the second object is the data in the second (right) list.
	 */
	@Prop() data: [TreeNode, TreeNode];

	/**
	 * Selected items in the transfer component in the form of an array of two arrays of item id strings. The first array is the selected items in the first(left) list and the second array is the selected items in the second (right) list.
	 */
	@Prop() selected: [string[], string[]];

	/** Attributes related to screen readers. */
	@Prop() aria: { leftButton?: string; rightButton?: string };

	/**
	 * Event emitted when either of the two transfer buttons are clicked to transfer items between the two lists. The event detail contains the direction of the transfer and the data in the two lists after the transfer.
	 */
	@Event({ eventName: "hbr-transfer" }) hbrTransfer: EventEmitter;

	@Listen("hbr-transfer")
	transferChangeHandler(event: CustomEvent) {
		if (event.detail.direction === "left") {
			this.transfer(
				this.data[1].children,
				this.data[0].children,
				this.selected[1],
			);
			event.detail.data = [this.data[1], this.data[0]];
		} else {
			this.transfer(
				this.data[0].children,
				this.data[1].children,
				this.selected[0],
			);
			event.detail.data = [this.data[0], this.data[1]];
		}
	}

	transfer = (
		source: TreeNode[],
		destination: TreeNode[],
		selected: string[],
	) => {
		for (let i = 0; i < source.length; i++) {
			const node = source[i];
			if (node.children && node.children.length > 0) {
				const selectedChildren = node.children.filter(
					(child) => child.id && selected.includes(child.id),
				);
				if (selectedChildren.length > 0) {
					const existingNode = destination.find((n) => n.id === node.id);
					if (existingNode) {
						existingNode.children = existingNode.children
							? [...existingNode.children, ...selectedChildren]
							: [...selectedChildren];
					} else {
						destination.push({ ...node, children: selectedChildren });
					}
					node.children = node.children.filter(
						(child) => child.id && !selected.includes(child.id),
					);
				}
			}
			if (node.id && selected.includes(node.id)) {
				const existingNode = destination.find((n) => n.id === node.id);
				if (!existingNode) {
					destination.push(node);
				}
				source.splice(i, 1);
				i--;
			}
		}
	};

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return (
			<div class="transfer--list-outer">
				<div class="transfer__list-container">
					<div class="transfer__source-check">
						<slot name="left-check-all" />
					</div>
					<div class="transfer__divider">
						<hbr-divider class="transfer__divider" />
					</div>
					<div class="transfer__search">
						<slot name="left-search-input" />
					</div>
					<div class="transfer__list">
						<slot name="left-list" />
					</div>
				</div>
				<div class="transfer__buttons-container">
					<div slot="left-transfer-button">
						<hbr-button
							disabled={this.selected[1].length === 0}
							onClick={() => this.hbrTransfer.emit({ direction: "left" })}
							data-testid="transfer--left-button"
							aria={{
								label:
									this.aria?.leftButton ||
									"Move selected items to the left list",
							}}
						>
							{" "}
							<hbr-icon
								asset={customSystemIcons?.["caret-left"] || caretLeft}
							/>
						</hbr-button>
					</div>
					<div slot="right-transfer-button">
						<hbr-button
							disabled={this.selected[0].length === 0}
							onClick={() => this.hbrTransfer.emit({ direction: "right" })}
							data-testid="transfer--right-button"
							aria={{
								label:
									this.aria?.rightButton ||
									"Move selected items to the right list",
							}}
						>
							{" "}
							<hbr-icon
								asset={customSystemIcons?.["caret-right"] || caretRight}
							/>
						</hbr-button>
					</div>
				</div>
				<div class="transfer__list-container">
					<div class="transfer__source-check">
						<slot name="right-check-all" />
					</div>
					<div class="transfer__divider">
						<hbr-divider class="transfer__divider" />
					</div>
					<div class="transfer__search">
						<slot name="right-search-input" />
					</div>
					<div class="transfer__list">
						<slot name="right-list" />
					</div>
				</div>
			</div>
		);
	}
}
